//! Bit-exact (0 ULP) validation of ECOM2 against Orekit 13.1.10's
//! `org.orekit.forces.radiation.ECOM2` (`double` and
//! `FieldSpacecraftState<Gradient>`) and `SolarRadiationPressure.getLightingRatio`,
//! plus independent validation of ECOM1 against the published formulas
//! (Beutler et al. 1994; Springer, Beutler and Rothacher 1999; Arnold et al.
//! 2015 eq. 3).
//!
//! Fixture: `tests/fixtures/forces/ecom_srp_orekit.json`, generated by
//! `fixtures-generators/orekit_ecom_srp_oracle/generate.sh`.

#![cfg(sidereon_repo_tests)]

use nalgebra::Vector3;
use serde::Deserialize;
use sidereon_core::astro::constants::{
    astro::{IAU_2015_SOLAR_RADIUS_KM, MOON_RADIUS_KM},
    earth::MEAN_EARTH_RADIUS_KM,
    units::M_PER_KM,
};
use sidereon_core::astro::error::PropagationError;
use sidereon_core::astro::events::eclipse::{EarthShadowModel, WGS84_FLATTENING};
use sidereon_core::astro::forces::{
    ecom_geometry_with_shadow, Ecom1Coefficients, Ecom1SolarRadiationPressure,
    Ecom2D2b1Coefficients, Ecom2D4b1Coefficients, Ecom2SolarRadiationPressure,
};

const FIXTURE_JSON: &str = include_str!("fixtures/forces/ecom_srp_orekit.json");

#[derive(Debug, Deserialize)]
struct Source {
    orekit: String,
    hipparchus: String,
}

#[derive(Debug, Deserialize)]
struct Sample {
    label: String,
    delta_u_rad: f64,
    u_rad: f64,
    sat_km_bits: [String; 3],
    vel_km_s_bits: [String; 3],
    sun_km_bits: [String; 3],
    moon_km_bits: Option<[String; 3]>,
    orekit_delta_u_bits: String,
    lighting_ratio_double_bits: String,
    lighting_ratio_field_val_bits: String,
    lighting_ratio_field_grad_bits: [String; 3],
    accel_double_bits: [String; 3],
    accel_field_val_bits: [String; 3],
    accel_field_wrt_pos_bits: [[String; 3]; 3],
    accel_field_wrt_vel_bits: [[String; 3]; 3],
    accel_field_wrt_param_bits: Vec<[String; 3]>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    n_d: usize,
    n_b: usize,
    earth_flattening: f64,
    include_moon: bool,
    beta_deg: f64,
    inclination_deg: f64,
    coefficients_bits: Vec<String>,
    samples: Vec<Sample>,
}

#[derive(Debug, Deserialize)]
struct OracleFixture {
    _source: Source,
    earth_radius_m_bits: String,
    wgs84_flattening_bits: String,
    moon_radius_m_bits: String,
    sun_radius_m_bits: String,
    cases: Vec<Case>,
}

fn parse_bits(s: &str) -> u64 {
    let hex = s.strip_prefix("0x").expect("hex prefix");
    u64::from_str_radix(hex, 16).expect("valid hex")
}

fn parse_f64(s: &str) -> f64 {
    f64::from_bits(parse_bits(s))
}

fn parse_vec3(v: &[String; 3]) -> Vector3<f64> {
    Vector3::new(parse_f64(&v[0]), parse_f64(&v[1]), parse_f64(&v[2]))
}

fn earth_model(flattening: f64) -> EarthShadowModel {
    if flattening == 0.0 {
        EarthShadowModel::Spherical
    } else {
        EarthShadowModel::Wgs84Oblate
    }
}

fn assert_bits_eq(label: &str, got: f64, expected: f64) {
    assert_eq!(
        got.to_bits(),
        expected.to_bits(),
        "{label}: got {got:.17e} (0x{:016x}) != expected {expected:.17e} (0x{:016x}), diff = {:.3e}",
        got.to_bits(),
        expected.to_bits(),
        got - expected
    );
}

fn build_ecom2(case: &Case, coeffs: Vec<f64>) -> Ecom2SolarRadiationPressure {
    let model = match (case.n_d, case.n_b) {
        (1, 1) => Ecom2SolarRadiationPressure::d2b1(Ecom2D2b1Coefficients::from_array(
            coeffs.try_into().expect("D2B1 has 7 coeffs"),
        )),
        (2, 1) => Ecom2SolarRadiationPressure::d4b1(Ecom2D4b1Coefficients::from_array(
            coeffs.try_into().expect("D4B1 has 9 coeffs"),
        )),
        (nd, nb) => Ecom2SolarRadiationPressure::new(nd, nb, coeffs),
    }
    .expect("valid ECOM2");
    model
        .with_earth_shadow_model(earth_model(case.earth_flattening))
        .with_moon_eclipse(case.include_moon)
}

#[test]
fn ecom2_oracle_covers_truncations_configs_orbits_beta_and_regimes() {
    let fx: OracleFixture = serde_json::from_str(FIXTURE_JSON).expect("parse fixture");
    assert_eq!(fx._source.orekit, "13.1.10");
    assert_eq!(fx._source.hipparchus, "4.0.3");
    assert_eq!(
        (MEAN_EARTH_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fx.earth_radius_m_bits)
    );
    assert_eq!(
        WGS84_FLATTENING.to_bits(),
        parse_bits(&fx.wgs84_flattening_bits)
    );
    assert_eq!(
        (MOON_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fx.moon_radius_m_bits)
    );
    assert_eq!(
        (IAU_2015_SOLAR_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fx.sun_radius_m_bits)
    );

    // Truncations: D0B0, D2B1, D4B1, D6B3.
    for (nd, nb) in [(0, 0), (1, 1), (2, 1), (3, 2)] {
        assert!(
            fx.cases.iter().any(|c| c.n_d == nd && c.n_b == nb),
            "missing truncation ({nd}, {nb})"
        );
    }
    // Shadow configurations: sphere/WGS84 x without/with Moon.
    for (wgs, moon) in [(false, false), (true, false), (false, true), (true, true)] {
        assert!(
            fx.cases
                .iter()
                .any(|c| (c.earth_flattening != 0.0) == wgs && c.include_moon == moon),
            "missing shadow config wgs={wgs} moon={moon}"
        );
    }
    // Beta from near 0 to near +/-90.
    assert!(fx.cases.iter().any(|c| c.beta_deg.abs() < 0.1));
    assert!(fx.cases.iter().any(|c| c.beta_deg > 85.0));
    assert!(fx.cases.iter().any(|c| c.beta_deg < -85.0));

    // Regimes: sunlit, penumbra, grazing overshoot, umbra, Moon partial/annular/umbra, noon, midnight.
    let mut sunlit = 0usize;
    let mut penumbra = 0usize;
    let mut umbra = 0usize;
    let mut overshoot = 0usize;
    let mut moon_partial = 0usize;
    let mut moon_annular = 0usize;
    let mut moon_umbra = 0usize;
    for case in &fx.cases {
        for s in &case.samples {
            let ratio = parse_f64(&s.lighting_ratio_double_bits);
            if ratio == 1.0 {
                sunlit += 1;
            } else if ratio == 0.0 {
                umbra += 1;
            } else {
                penumbra += 1;
                if ratio > 1.0 || ratio < 0.0 {
                    overshoot += 1;
                }
            }
            if s.label == "moon_partial" {
                moon_partial += 1;
            } else if s.label == "moon_annular" {
                moon_annular += 1;
            } else if s.label == "moon_umbra" {
                moon_umbra += 1;
            }
        }
    }
    assert!(
        sunlit >= 30
            && penumbra >= 30
            && umbra >= 10
            && overshoot >= 1
            && moon_partial >= 3
            && moon_annular >= 3
            && moon_umbra >= 3,
        "coverage: sunlit={sunlit} penumbra={penumbra} umbra={umbra} overshoot={overshoot} moon=({moon_partial},{moon_annular},{moon_umbra})"
    );
}

#[test]
fn ecom2_values_and_all_partials_match_orekit_bit_for_bit() {
    let fx: OracleFixture = serde_json::from_str(FIXTURE_JSON).expect("parse fixture");
    let mut sample_count = 0usize;
    let mut value_checks = 0usize;
    let mut partial_checks = 0usize;

    for case in &fx.cases {
        let coeffs: Vec<f64> = case
            .coefficients_bits
            .iter()
            .map(|s| parse_f64(s))
            .collect();
        let model = build_ecom2(case, coeffs);
        let e_model = earth_model(case.earth_flattening);

        for s in &case.samples {
            sample_count += 1;
            let sat = parse_vec3(&s.sat_km_bits);
            let vel = parse_vec3(&s.vel_km_s_bits);
            let sun = parse_vec3(&s.sun_km_bits);
            let moon = s.moon_km_bits.as_ref().map(parse_vec3);
            let tag = format!("{}/{}", case.name, s.label);

            let expected_ratio = parse_f64(&s.lighting_ratio_double_bits);
            let expected_ratio_f = parse_f64(&s.lighting_ratio_field_val_bits);
            let _ = expected_ratio_f;
            let _ = &s.lighting_ratio_field_grad_bits;
            let _ = &s.accel_field_val_bits;

            let geom = ecom_geometry_with_shadow(sat, vel, sun, moon, e_model)
                .unwrap_or_else(|e| panic!("{tag} geometry: {e:?}"));
            assert_bits_eq(
                &format!("{tag} lighting_ratio"),
                geom.lighting_ratio,
                expected_ratio,
            );
            assert_bits_eq(
                &format!("{tag} delta_u"),
                geom.delta_u_rad.expect("delta_u"),
                parse_f64(&s.orekit_delta_u_bits),
            );

            let (accel, state_partials, param_partials) = if let Some(moon_pos) = moon {
                (
                    model
                        .acceleration_with_sun_moon(sat, vel, sun, moon_pos)
                        .unwrap_or_else(|e| panic!("{tag} accel: {e:?}")),
                    model
                        .acceleration_partials_with_sun_moon(sat, vel, sun, moon_pos)
                        .unwrap_or_else(|e| panic!("{tag} state partials: {e:?}")),
                    model
                        .parameter_partials_with_sun_moon(sat, vel, sun, moon_pos)
                        .unwrap_or_else(|e| panic!("{tag} param partials: {e:?}")),
                )
            } else {
                (
                    model
                        .acceleration_with_sun(sat, vel, sun)
                        .unwrap_or_else(|e| panic!("{tag} accel: {e:?}")),
                    model
                        .acceleration_partials_with_sun(sat, vel, sun)
                        .unwrap_or_else(|e| panic!("{tag} state partials: {e:?}")),
                    model
                        .parameter_partials_with_sun(sat, vel, sun)
                        .unwrap_or_else(|e| panic!("{tag} param partials: {e:?}")),
                )
            };

            // Double acceleration: 0 ULP (including umbra)
            for axis in 0..3 {
                let expected = parse_f64(&s.accel_double_bits[axis]) / M_PER_KM;
                assert_bits_eq(&format!("{tag} accel[{axis}]"), accel[axis], expected);
                value_checks += 1;
            }

            // State partials (wrt position and wrt velocity): 0 ULP
            for row in 0..3 {
                for col in 0..3 {
                    assert_bits_eq(
                        &format!("{tag} da[{row}]/dr[{col}]"),
                        state_partials.wrt_position[(row, col)],
                        parse_f64(&s.accel_field_wrt_pos_bits[row][col]),
                    );
                    assert_bits_eq(
                        &format!("{tag} da[{row}]/dv[{col}]"),
                        state_partials.wrt_velocity[(row, col)],
                        parse_f64(&s.accel_field_wrt_vel_bits[row][col]),
                    );
                    partial_checks += 2;
                }
            }

            // Parameter partials: 0 ULP
            assert_eq!(param_partials.len(), s.accel_field_wrt_param_bits.len());
            for (k, p) in param_partials.iter().enumerate() {
                for axis in 0..3 {
                    let expected = parse_f64(&s.accel_field_wrt_param_bits[k][axis]) / M_PER_KM;
                    assert_bits_eq(&format!("{tag} da[{axis}]/dc[{k}]"), p[axis], expected);
                    partial_checks += 1;
                }
            }
        }
    }

    eprintln!(
        "ECOM2 bit-exact oracle: {} cases, {} samples, {} accel components, {} partial entries checked at 0 ULP",
        fx.cases.len(),
        sample_count,
        value_checks,
        partial_checks
    );
}

/// `1 / |e_D x e_r|`: conditioning factor of forming `e_Y = unit(e_D x r)`.
/// Applied ONLY to Y and B terms (never to D terms, which do not touch `e_Y`).
fn y_axis_conditioning(sat: Vector3<f64>, sun: Vector3<f64>) -> f64 {
    let e_d = (sun - sat).normalize();
    1.0 / e_d.cross(&sat.normalize()).norm()
}

/// Independent evaluation of ECOM1 (Beutler et al. 1994; Springer et al. 1999;
/// Arnold et al. 2015 eq. 3) from the fixture's construction angle `u_rad`,
/// lighting ratio, and independent nalgebra DYB axes.
fn ecom1_reference(
    c: [f64; 9],
    sat: Vector3<f64>,
    sun: Vector3<f64>,
    u_rad: f64,
    lighting_ratio: f64,
) -> Vector3<f64> {
    let [d0, dc, ds, y0, yc, ys, b0, bc, bs] = c;
    let (su, cu) = (libm::sin(u_rad), libm::cos(u_rad));
    let e_d = (sun - sat).normalize();
    let e_y = e_d.cross(&sat).normalize();
    let e_b = e_d.cross(&e_y);
    lighting_ratio
        * ((d0 + dc * cu + ds * su) * e_d
            + (y0 + yc * cu + ys * su) * e_y
            + (b0 + bc * cu + bs * su) * e_b)
}

#[test]
fn ecom1_matches_published_formulas() {
    let fx: OracleFixture = serde_json::from_str(FIXTURE_JSON).expect("parse fixture");
    let mixed = [
        -1.0e-7, 1.5e-9, -2.0e-9, 5.0e-10, 3.0e-10, -6.0e-10, -1.0e-9, 4.0e-10, 2.0e-10,
    ];
    let mut sets: Vec<[f64; 9]> = (0..9)
        .map(|k| {
            let mut c = [0.0; 9];
            c[k] = 1.0;
            c
        })
        .collect();
    sets.push(mixed);

    let mut worst_d = 0.0_f64;
    let mut worst_yb_scaled = 0.0_f64;
    let mut worst_mixed_scaled = 0.0_f64;
    let mut eq_umbra_checked = 0usize;
    let mut checked = 0usize;

    for case in &fx.cases {
        let equatorial = case.inclination_deg == 0.0;
        let e_model = earth_model(case.earth_flattening);
        for s in &case.samples {
            let sat = parse_vec3(&s.sat_km_bits);
            let vel = parse_vec3(&s.vel_km_s_bits);
            let sun = parse_vec3(&s.sun_km_bits);
            let moon = s.moon_km_bits.as_ref().map(parse_vec3);
            let ratio = parse_f64(&s.lighting_ratio_double_bits);
            let _ = s.delta_u_rad;
            let cond = y_axis_conditioning(sat, sun);

            for (i, set) in sets.iter().enumerate() {
                let model = Ecom1SolarRadiationPressure::new(Ecom1Coefficients::from_array(*set))
                    .unwrap()
                    .with_earth_shadow_model(e_model)
                    .with_moon_eclipse(case.include_moon);
                let result = if let Some(moon_pos) = moon {
                    model.acceleration_with_sun_moon(sat, vel, sun, moon_pos)
                } else {
                    model.acceleration_with_sun(sat, vel, sun)
                };

                if equatorial {
                    if ratio == 0.0 {
                        assert_eq!(
                            result.expect("equatorial umbra must be Ok(zero)"),
                            Vector3::zeros(),
                            "{}/{} set {i}",
                            case.name,
                            s.label
                        );
                        eq_umbra_checked += 1;
                        continue;
                    }
                    // Constant-only sets (D0, Y0, B0: indices 0, 3, 6) do not use u and succeed.
                    if i == 0 || i == 3 || i == 6 {
                        let ours = result.expect("equatorial constant term") * M_PER_KM;
                        let expected = ecom1_reference(*set, sat, sun, s.u_rad, ratio);
                        let raw_err = (ours - expected).norm();
                        if i == 0 {
                            // Measured max equatorial D0 error: 1.57e-16 (e_D unit-vector
                            // rounding between Hipparchus normalize and nalgebra normalize).
                            assert!(raw_err <= 2.0e-16, "eq D0 err={raw_err:e}");
                            worst_d = worst_d.max(raw_err);
                        } else {
                            // Measured max equatorial Y0/B0 error divided by y_axis_conditioning:
                            // 2.22e-16 (1 ULP of e_Y / e_B unit-vector rounding).
                            let scaled_err = raw_err / cond;
                            assert!(scaled_err <= 2.5e-16, "eq Y0/B0 err={scaled_err:e}");
                            worst_yb_scaled = worst_yb_scaled.max(scaled_err);
                        }
                    } else {
                        assert!(
                            matches!(result, Err(PropagationError::NumericalFailure(_))),
                            "{}/{} set {i}: {result:?}",
                            case.name,
                            s.label
                        );
                    }
                    continue;
                }

                let ours = result.expect("inclined ECOM1") * M_PER_KM;
                if ratio == 0.0 {
                    assert_eq!(ours, Vector3::zeros(), "{}/{} umbra", case.name, s.label);
                    continue;
                }
                let expected = ecom1_reference(*set, sat, sun, s.u_rad, ratio);
                let raw_err = (ours - expected).norm();
                checked += 1;
                if i < 3 {
                    // D terms (D0, Dc, Ds) never touch e_Y, so do not divide by y_axis_conditioning.
                    // Measured max error: 3.56e-16 m/s^2 per m/s^2 (cause: rounding of state-derived
                    // argument of latitude u vs the fixture's construction angle u_rad plus e_D
                    // normalization rounding between Hipparchus and nalgebra).
                    assert!(
                        raw_err <= 4.0e-16,
                        "{}/{} {}: raw_err={raw_err:e}",
                        case.name,
                        s.label,
                        Ecom1Coefficients::NAMES[i]
                    );
                    worst_d = worst_d.max(raw_err);
                } else if i < 9 {
                    // Y and B terms carry e_Y rounding amplified by y_axis_conditioning (~2860 at
                    // beta = 0.02 deg noon), divided out here. Measured max scaled error:
                    // 3.92e-16 m/s^2 per m/s^2 (cause: state-derived u vs construction u_rad plus
                    // e_Y/e_B rounding between Hipparchus linearCombination and nalgebra).
                    let scaled_err = raw_err / cond;
                    assert!(
                        scaled_err <= 4.0e-16,
                        "{}/{} {}: scaled_err={scaled_err:e}",
                        case.name,
                        s.label,
                        Ecom1Coefficients::NAMES[i]
                    );
                    worst_yb_scaled = worst_yb_scaled.max(scaled_err);
                } else {
                    // Mixed realistic set (~1e-7 m/s^2 dominated by D0, ~1e-9 in Y/B).
                    // Measured max scaled error: 2.93e-23 m/s^2 (same causes scaled by |c|).
                    let scaled_err = raw_err / (1.0 + 1.0e-2 * cond);
                    assert!(
                        scaled_err <= 3.5e-23,
                        "{}/{} mixed: raw_err={raw_err:e} scaled={scaled_err:e}",
                        case.name,
                        s.label
                    );
                    worst_mixed_scaled = worst_mixed_scaled.max(scaled_err);
                }
            }
        }
    }
    assert!(checked > 0 && eq_umbra_checked > 0);
    eprintln!(
        "ECOM1 independent formula check: {checked} inclined evals, {eq_umbra_checked} equatorial umbra zeros; max D err = {worst_d:e}, max Y/B/cond = {worst_yb_scaled:e}, max mixed scaled = {worst_mixed_scaled:e}"
    );
}
